Append sets to each key’s sorted history; binary search returns the latest value at or before each get time. Call solve(operations) directly; it returns one result per get.

```javascript
function solve(operations) {
  const histories = new Map();
  const results = [];

  for (const operation of operations) {
    const [type, key] = operation;

    if (type === "set") {
      const [, , value, time] = operation;
      if (!histories.has(key)) histories.set(key, []);
      histories.get(key).push([time, value]);
    } else if (type === "get") {
      const time = operation[2];
      const history = histories.get(key) || [];
      let left = 0;
      let right = history.length;

      while (left < right) {
        const mid = left + Math.floor((right - left) / 2);
        if (history[mid][0] <= time) {
          left = mid + 1;
        } else {
          right = mid;
        }
      }

      results.push(left === 0 ? null : history[left - 1][1]);
    }
  }

  return results;
}
```

Each set takes amortized O(1); each get takes O(log(h + 1)), where h is that key’s history length. Space is O(S + G), including S stored sets and G returned query results.

